73	@RestController
74	@CrossOrigin(exposedHeaders = "errors, content-type")
75	@RequestMapping("/api")
76	public class OwnerRestControllerV1 implements OwnersApi {
77	
78	    /** Dedicated audit logger for owner lifecycle side-effects. */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    /** Dedicated notification logger for owner welcome notifications. */
82	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
83	
84	    /** Serializes {@link OwnerCreatedEvent} instances to their JSON audit representation. */
85	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
86	
87	    /** Monotonically increasing sequence stamped on every structured owner-created event. */
88	    private static final AtomicLong AUDIT_SEQ = new AtomicLong();
89	
90	    /** Schema version stamped on every structured owner-created event (version 2). */
91	    private static final int AUDIT_SCHEMA_VERSION = 2;
92	
93	    /**
94	     * Immutable structured audit event emitted once per owner create. Carries the audit
95	     * {@code schemaVersion} (2 under the version-2 identity) and the owner's <em>current
96	     * primary identifier</em> in {@code memberId}, as returned by
97	     * {@link #primaryIdentifier(Owner)} (the unified, version-2 memberId).
98	     */
99	    private record OwnerCreatedEvent(long seq, int schemaVersion, Integer ownerId, String memberId,
100	            Integer membershipLevel, String event) {
101	    }
102	
103	    /**
104	     * Pragmatic check for a syntactically valid email address: a non-empty local
105	     * part, a single '@', and a domain with at least one dot-separated label.
106	     */
107	    private static final Pattern EMAIL_PATTERN =
108	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
109	
110	    /**
111	     * Disposable email domains that are rejected: an owner email whose domain is one of
112	     * these is treated as invalid so the create/update is rejected with 400. Compared
113	     * case-insensitively against the normalized (lower-cased) email domain.
114	     */
115	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
116	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
117	
118	    /**
119	     * Common street-type abbreviations expanded during address normalization,
120	     * keyed by their upper-cased form.
121	     */
122	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
123	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
124	
125	    /**
126	     * Required national-number length keyed by E.164 country calling code: a
127	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
128	     * (NANP) number carries 10. A number whose country code is listed here must have
129	     * exactly the mandated number of national digits.
130	     */
131	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
132	        Map.of("61", 9, "1", 10);
133	
134	    /**
135	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
136	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
137	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
138	     * postcode.
139	     */
140	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
141	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
142	            "QLD", new int[] {4000, 4099});
143	
144	    /** HTTP header carrying the client-supplied idempotency key for owner creation. */
145	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
146	
147	    /**
148	     * Remembers the owner created for each seen {@code Idempotency-Key}, so a create that
149	     * repeats with an already-seen key returns the originally created owner (200) instead of
150	     * creating a duplicate. Kept in-memory and keyed by the raw header value.
151	     */
152	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
153	
154	    private final ClinicService clinicService;
155	
156	    private final OwnerMapper ownerMapper;
157	
158	    private final PetMapper petMapper;
159	
160	    private final VisitMapper visitMapper;
