163	                                 OwnerMapper ownerMapper,
164	                                 PetMapper petMapper,
165	                                 VisitMapper visitMapper) {
166	        this.clinicService = clinicService;
167	        this.ownerMapper = ownerMapper;
168	        this.petMapper = petMapper;
169	        this.visitMapper = visitMapper;
170	    }
