172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
175	        Collection<Owner> owners;
176	        if (lastName != null) {
177	            owners = this.clinicService.findOwnerByLastName(lastName);
178	        } else {
179	            owners = this.clinicService.findAllOwners();
180	        }
181	        if (owners.isEmpty()) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
185	    }
