187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
190	        Owner owner = this.clinicService.findOwnerById(ownerId);
191	        if (owner == null) {
192	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	        }
194	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
200	        // Idempotent create: when the request carries an 'Idempotency-Key' already seen on a
201	        // previous successful create, return the originally created owner with 200 instead of
202	        // creating a duplicate.
203	        String idempotencyKey = currentIdempotencyKey();
204	        if (idempotencyKey != null) {
205	            Integer existingId = idempotentCreates.get(idempotencyKey);
206	            if (existingId != null) {
207	                Owner existing = this.clinicService.findOwnerById(existingId);
208	                if (existing != null) {
209	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
210	                }
211	            }
212	        }
213	        // Validate & normalize the optional email; reject the create when it is present but invalid.
214	        if (!normalizeEmail(ownerFieldsDto)) {
215	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
216	                "The supplied email address is invalid");
217	        }
218	        // Validate & normalize the optional postcode; reject the create when it is present but
219	        // not valid for the owner's city (see normalizePostcode).
220	        if (!normalizePostcode(ownerFieldsDto)) {
221	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
222	                "The supplied postcode is invalid for the owner's city");
223	        }
224	        // Normalize the supplied address — the structured 'addressLine1'/'addressLine2' when
225	        // present, otherwise the flat 'address' — storing the normalized form (and the composed
226	        // 'address') back on the DTO so it is what gets persisted and compared. Reject the create
227	        // when no address is supplied in either form (see normalizeAddresses).
228	        if (!normalizeAddresses(ownerFieldsDto)) {
229	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
230	                "An address is required (supply either 'addressLine1' or 'address')");
231	        }
232	        // Reject the create when the owner's city is already at capacity, i.e. it already
233	        // contains 50 or more owners (compared case-insensitively).
234	        int ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
235	        if (ownersInCity >= 50) {
236	            throw new RestRejectionException(HttpStatus.CONFLICT,
237	                "The owner's city has reached its capacity limit");
238	        }
239	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
240	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
241	        if (normalizedTelephone == null) {
242	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
243	                "The supplied telephone number is invalid");
244	        }
245	        ownerFieldsDto.setTelephone(normalizedTelephone);
246	        // Consolidated duplicate detection. All duplicate checks are now expressed through the
247	        // single derived identity key: the SHA-256 hex of
248	        // '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>' (see OwnerMapper#identityKey).
249	        // A create is rejected with 409 only when the new owner's identity key collides with an
250	        // existing (non-deleted) owner's. Because the telephone is part of the key, two owners with
251	        // the same last name and postcode but different telephones no longer collide — they are
252	        // created (and may be flagged as a soft match below), not rejected. The former separate
253	        // household-duplicate 409 keyed on the computed householdId no longer applies.
254	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
255	        String identityKey = ownerMapper.identityKey(candidate);
256	        boolean identityInUse = this.clinicService.findAllOwners().stream()
257	            .filter(existing -> !existing.isDeleted())
258	            .anyMatch(existing -> identityKey.equals(ownerMapper.identityKey(existing)));
259	        if (identityInUse) {
260	            throw new RestRejectionException(HttpStatus.CONFLICT,
261	                "An owner with the same identity already exists");
262	        }
263	        // Determine the effective registration date — the value supplied on the request, or the
264	        // server's current date when none was supplied — and roll it forward to the next business
265	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
266	        // registration date (membership-number year segment, per-day create-limit) uses this
267	        // adjusted date.
268	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
269	        if (registrationDate == null) {
270	            registrationDate = LocalDate.now();
271	        }
272	        // Reject a supplied registration date that lies in the future (later than the
273	        // server's current date): an owner cannot be registered ahead of time.
274	        else if (registrationDate.isAfter(LocalDate.now())) {
275	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
276	                "The registration date cannot be in the future");
277	        }
278	        registrationDate = toBusinessDay(registrationDate);
279	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
280	        // owners have already been registered on this (adjusted) business day.
281	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
282	            throw new RestRejectionException(HttpStatus.TOO_MANY_REQUESTS,
283	                "The daily owner sign-up limit has been reached");
284	        }
285	        HttpHeaders headers = new HttpHeaders();
286	        Owner owner = candidate;
287	        owner.setRegistrationDate(registrationDate);
288	        // Assign the unified memberId as '<REGION><FY><HASH8><CHK>': the region derived from the
289	        // owner's postcode (falling back to the city, then 'UNKNOWN'), the two-digit fiscal year of
290	        // the registration date, the first 8 upper-case hex characters of the SHA-256 of the
291	        // normalized telephone concatenated with the last name, and a single Luhn check digit over
292	        // the digits of '<REGION><FY><HASH8>'.
293	        owner.setMemberId(memberId(owner));
294	        // Record how many existing owners already share this owner's first and last name
295	        // (compared case-insensitively) at the moment before this owner is created.
296	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
297	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
298	        // registered on this (adjusted) business day before this owner is created.
299	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
300	        // Flag that the owner's city is approaching its capacity limit: it already held between
301	        // 40 and 49 owners (inclusive) before this owner was created. The hard rejection at 50
302	        // owners is handled above, so reaching this point means the count is below 50.
303	        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
304	        // Record the size of this owner's household after this create: the number of existing
305	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
306	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
307	        // Cap this owner's membership level at one above the current maximum membership level among
308	        // their existing household members. When the owner has no existing household member no cap
309	        // applies (a null cap; see OwnerMapper#membershipLevel).
310	        owner.setMembershipLevelCap(membershipLevelCap(owner));
311	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate (its
312	        // identity key is distinct), but it shares an existing owner's Soundex last name and
313	        // postcode. When such a match exists, record it as 'possibleDuplicate' with
314	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
315	        // duplicate. A declared household member (the request sets 'sharesHousehold') is an
316	        // acknowledged member, not a suspected duplicate, so it is never flagged.
317	        Owner softMatch = findPossibleDuplicate(owner);
318	        boolean declaredMember = softMatch != null && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
319	        if (declaredMember) {
320	            owner.setPossibleDuplicate(false);
321	            owner.setPossibleDuplicateOf(null);
322	        }
323	        else {
324	            owner.setPossibleDuplicate(softMatch != null);
325	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
326	        }
327	        this.clinicService.saveOwner(owner);
328	        // Emit an audit line recording the new owner's id, memberId, registration date and
329	        // membership level.
330	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
331	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
332	            ownerMapper.membershipLevel(owner));
333	        // Emit the immutable structured OWNER_CREATED event (audit schema version 2) carrying a
334	        // monotonically increasing sequence, the schema version, and the owner's current primary
335	        // identifier (the version-2 memberId).
336	        OwnerCreatedEvent event = new OwnerCreatedEvent(AUDIT_SEQ.incrementAndGet(),
337	            AUDIT_SCHEMA_VERSION, owner.getId(), primaryIdentifier(owner),
338	            ownerMapper.membershipLevel(owner), "OWNER_CREATED");
339	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
340	        // Enqueue a welcome notification for the newly created owner, carrying its id and memberId.
341	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
342	        // Remember this create against its idempotency key so a later repeat returns the same
343	        // owner instead of creating a duplicate.
344	        if (idempotencyKey != null) {
345	            idempotentCreates.put(idempotencyKey, owner.getId());
346	        }
347	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
348	        headers.setLocation(UriComponentsBuilder.newInstance()
349	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
350	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
351	    }
352	
353	    /**
354	     * The non-blank {@code Idempotency-Key} header of the current request, or {@code null} when
355	     * absent, blank, or there is no bound request.
356	     */
357	    private static String currentIdempotencyKey() {
358	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
359	        if (!(attributes instanceof org.springframework.web.context.request.ServletRequestAttributes servletAttributes)) {
360	            return null;
361	        }
362	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
363	        return (key == null || key.isBlank()) ? null : key;
364	    }
365	
366	    /**
367	     * Validate and normalize the optional owner email in place.
368	     *
369	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
370	     * When present it must be a syntactically valid address; a valid address is
371	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
372	     * present but syntactically invalid, so the caller can reject with 400.
373	     */
374	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
375	        String email = ownerFieldsDto.getEmail();
376	        if (email == null || email.isBlank()) {
377	            ownerFieldsDto.setEmail(null);
378	            return true;
379	        }
380	        String normalized = email.trim().toLowerCase(Locale.ROOT);
381	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
382	            return false;
383	        }
384	        // Reject addresses whose domain is on the disposable-domain blocklist.
385	        String domain = normalized.substring(normalized.indexOf('@') + 1);
386	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
387	            return false;
388	        }
389	        ownerFieldsDto.setEmail(normalized);
390	        return true;
391	    }
392	
393	    /**
394	     * Validate the optional owner postcode in place.
395	     *
396	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
397	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
398	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
399	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
400	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
401	     * when a postcode is present but malformed or out of range, so the caller can
402	     * reject with 400.
403	     */
404	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
405	        String postcode = ownerFieldsDto.getPostcode();
406	        if (postcode == null || postcode.isBlank()) {
407	            ownerFieldsDto.setPostcode(null);
408	            return true;
409	        }
410	        if (!postcode.matches("\\d{4}")) {
411	            return false;
412	        }
413	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
414	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
415	        if (range != null) {
416	            int value = Integer.parseInt(postcode);
417	            if (value < range[0] || value > range[1]) {
418	                return false;
419	            }
420	        }
421	        return true;
422	    }
423	
424	    /**
425	     * Validate and normalize the owner's address fields in place, preferring the structured
426	     * form over the flat 'address' for backward compatibility.
427	     *
428	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
429	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
430	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
431	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
432	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
433	     * cleared. Returns {@code false} when no address is supplied in either form (both the
434	     * structured addressLine1 and the flat address are blank once normalized), so the caller
435	     * can reject with 400.
436	     */
437	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
438	        String rawLine1 = ownerFieldsDto.getAddressLine1();
439	        if (rawLine1 != null && !rawLine1.isBlank()) {
440	            String line1 = normalizeAddress(rawLine1);
441	            if (line1.isBlank()) {
442	                return false;
443	            }
444	            ownerFieldsDto.setAddressLine1(line1);
445	            String rawLine2 = ownerFieldsDto.getAddressLine2();
446	            String composed = line1;
447	            if (rawLine2 != null && !rawLine2.isBlank()) {
448	                String line2 = normalizeAddress(rawLine2);
449	                ownerFieldsDto.setAddressLine2(line2);
450	                composed = line1 + " " + line2;
451	            }
452	            else {
453	                ownerFieldsDto.setAddressLine2(null);
454	            }
455	            ownerFieldsDto.setAddress(composed);
456	            return true;
457	        }
458	        // No structured address: fall back to the flat 'address' input.
459	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
460	        if (canonicalAddress.isBlank()) {
461	            return false;
462	        }
463	        ownerFieldsDto.setAddress(canonicalAddress);
464	        ownerFieldsDto.setAddressLine1(null);
465	        ownerFieldsDto.setAddressLine2(null);
466	        return true;
467	    }
468	
469	    /**
470	     * Normalize an owner address: trim, collapse each run of whitespace to a single
471	     * space, upper-case, and expand common street-type abbreviations
472	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
473	     * A {@code null} value normalizes to the empty string.
474	     */
475	    private static String normalizeAddress(String value) {
476	        if (value == null) {
477	            return "";
478	        }
479	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
480	        if (collapsed.isEmpty()) {
481	            return "";
482	        }
483	        String[] tokens = collapsed.split(" ");
484	        StringBuilder sb = new StringBuilder(collapsed.length());
485	        for (int i = 0; i < tokens.length; i++) {
486	            if (i > 0) {
487	                sb.append(' ');
488	            }
489	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
490	        }
491	        return sb.toString();
492	    }
493	
494	    /**
495	     * Normalize a telephone number to E.164 form.
496	     *
497	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
498	     * explicit leading {@code '+'} and country code it is kept; otherwise the
499	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
500	     * dropped from the national digits. The result must contain 8 to 15 digits
501	     * after the {@code '+'}, and — for a recognised country calling code — exactly
502	     * the national-number length that code mandates ({@code '+61'} => 9 national
503	     * digits, {@code '+1'} => 10).
504	     *
505	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
506	     *         the input is absent or cannot form a valid E.164 number.
507	     */
508	    private static String toE164(String raw) {
509	        if (raw == null) {
510	            return null;
511	        }
512	        String trimmed = raw.trim();
513	        boolean hasCountryCode = trimmed.startsWith("+");
514	        // Strip spaces, dashes and brackets.
515	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
516	        String digits;
517	        if (hasCountryCode) {
518	            // Keep the explicit country code; drop the leading '+' for validation.
519	            digits = stripped.substring(1);
520	        } else {
521	            // No country code: assume '+61' and drop a single leading '0'.
522	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
523	            digits = "61" + national;
524	        }
525	        if (!digits.matches("\\d{8,15}")) {
526	            return null;
527	        }
528	        // For a recognised country calling code, enforce the exact national-number length it
529	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
530	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
531	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
532	                .sorted((a, b) -> b.length() - a.length()).toList()) {
533	            if (digits.startsWith(countryCode)) {
534	                int nationalLength = digits.length() - countryCode.length();
535	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
536	                    return null;
537	                }
538	                break;
539	            }
540	        }
541	        return "+" + digits;
542	    }
