570	    /**
571	     * Compute the membership-level cap for the owner being created: one above the current maximum
572	     * effective membership level among its existing (non-deleted) household members, i.e. those
573	     * sharing its computed householdId. Each member's effective level is read through
574	     * {@link OwnerMapper#membershipLevel(Owner)}, so it already reflects any cap applied to that
575	     * member. Returns {@code null} when the owner has no existing household member, in which case
576	     * no cap applies.
577	     */
578	    private Integer membershipLevelCap(Owner owner) {
579	        String householdId = ownerMapper.householdId(owner);
580	        java.util.OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
581	            .filter(existing -> !existing.isDeleted())
582	            .filter(existing -> existing != owner)
583	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
584	            .mapToInt(existing -> ownerMapper.membershipLevel(existing))
585	            .max();
586	        return maxLevel.isPresent() ? maxLevel.getAsInt() + 1 : null;
587	    }
