589	    /**
590	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
591	     * of: one whose identity key differs (so it is not a hard duplicate) yet whose last name shares
592	     * the same Soundex code and whose postcode is the same. Owners without a postcode never match
593	     * (the postcode must be shared) and deleted owners are ignored. When several existing owners
594	     * match, the one with the lowest id is returned so the result is deterministic. Returns
595	     * {@code null} when there is no such match.
596	     */
597	    private Owner findPossibleDuplicate(Owner candidate) {
598	        if (candidate.getPostcode() == null) {
599	            return null;
600	        }
601	        String candidateKey = ownerMapper.identityKey(candidate);
602	        String candidateSoundex = Soundex.of(candidate.getLastName());
603	        return this.clinicService.findAllOwners().stream()
604	            .filter(existing -> !existing.isDeleted())
605	            .filter(existing -> !candidateKey.equals(ownerMapper.identityKey(existing)))
606	            .filter(existing -> candidate.getPostcode().equals(existing.getPostcode())
607	                && candidateSoundex.equals(Soundex.of(existing.getLastName())))
608	            .min(java.util.Comparator.comparing(Owner::getId))
609	            .orElse(null);
610	    }
