612	    /**
613	     * The owner's current primary identifier, as carried by structured audit events: the
614	     * unified memberId.
615	     */
616	    private String primaryIdentifier(Owner owner) {
617	        return owner.getMemberId();
618	    }
619	
620	    /**
621	     * Build the owner's unified memberId, formatted {@code '<REGION><FY><HASH8><CHK>'}.
622	     *
623	     * <p>Under version 2, {@code REGION} is the region derived from the owner's postcode (see
624	     * {@link #deriveRegion}) with the fixed {@link OwnerMapper#VERSION_TAG 'V2'} version tag
625	     * mixed in as a prefix (e.g. {@code 'V2NSW'}), so no memberId produced under version 1 is
626	     * produced again. {@code FY} is the two-digit fiscal year (starting 1 July) of the
627	     * business-day-adjusted registration date. {@code HASH8} is the first 8 upper-case hex
628	     * characters of the SHA-256 of the 'V2' version tag, the normalized telephone and the last
629	     * name. {@code CHK} is a single Luhn check digit computed over the digits of
630	     * {@code '<REGION><FY><HASH8>'} (e.g. {@code 'V2NSW271A2B3C4D5'}).
631	     *
632	     * <p>The 'V2' tag lives only inside this identifier; the user-facing locality, timezone and
633	     * owner segment continue to report the plain region (e.g. 'NSW').
634	     *
635	     * <p>When the computed memberId collides with an existing owner's memberId, it is
636	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
637	     * that makes it unique.
638	     */
639	    private String memberId(Owner owner) {
640	        String region = OwnerMapper.VERSION_TAG + deriveRegion(owner.getPostcode(), owner.getCity());
641	        String fy = String.format("%02d", fiscalYearTwoDigits(owner.getRegistrationDate()));
642	        String hash8 = sha256HexUpper(
643	            OwnerMapper.VERSION_TAG + "|" + owner.getTelephone() + owner.getLastName(), 8);
644	        String base = region + fy + hash8;
645	        String memberId = base + luhn(base);
646	        Set<String> existing = this.clinicService.findAllOwners().stream()
647	            .map(Owner::getMemberId)
648	            .filter(java.util.Objects::nonNull)
649	            .collect(Collectors.toSet());
650	        if (!existing.contains(memberId)) {
651	            return memberId;
652	        }
653	        int n = 2;
654	        while (existing.contains(memberId + "-" + n)) {
655	            n++;
656	        }
657	        return memberId + "-" + n;
658	    }
659	
660	    /**
661	     * The two-digit fiscal year (starting 1 July) of the given date: the last two digits of the
662	     * calendar year in which the fiscal year ends. Dates on or after 1 July belong to the fiscal
663	     * year ending the following calendar year (e.g. 2026-08-10 -&gt; 27); earlier dates belong to
664	     * the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt; 26).
665	     */
666	    private static int fiscalYearTwoDigits(LocalDate date) {
667	        int endYear = date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
668	        return endYear % 100;
669	    }
670	
671	    /**
672	     * A single Luhn check digit (0-9) computed over the digit characters contained in
673	     * {@code value}; non-digit characters are ignored.
674	     */
675	    private static int luhn(String value) {
676	        int sum = 0;
677	        boolean dbl = true;
678	        for (int i = value.length() - 1; i >= 0; i--) {
679	            char c = value.charAt(i);
680	            if (c < '0' || c > '9') {
681	                continue;
682	            }
683	            int d = c - '0';
684	            if (dbl) {
685	                d *= 2;
686	                if (d > 9) {
687	                    d -= 9;
688	                }
689	            }
690	            sum += d;
691	            dbl = !dbl;
692	        }
693	        return (10 - (sum % 10)) % 10;
694	    }
695	
696	    /**
697	     * Derive the owner's region, preferring the postcode. The postcode is matched against
698	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
699	     * it is absent or in no known range does this fall back to the fixed city-to-region table
700	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
701	     */
702	    private static String deriveRegion(String postcode, String city) {
703	        if (postcode != null && postcode.matches("\\d{4}")) {
704	            int value = Integer.parseInt(postcode);
705	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
706	                int[] range = entry.getValue();
707	                if (value >= range[0] && value <= range[1]) {
708	                    return entry.getKey();
709	                }
710	            }
711	        }
712	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
713	    }
714	
715	    /**
716	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
717	     * bytes of {@code value}.
718	     */
719	    private static String sha256HexUpper(String value, int length) {
720	        try {
721	            byte[] digest = MessageDigest.getInstance("SHA-256")
722	                .digest(value.getBytes(StandardCharsets.UTF_8));
723	            StringBuilder sb = new StringBuilder(digest.length * 2);
724	            for (byte b : digest) {
725	                sb.append(String.format("%02X", b));
726	            }
727	            return sb.substring(0, length);
728	        }
729	        catch (NoSuchAlgorithmException e) {
730	            throw new IllegalStateException(e);
731	        }
732	    }
