755	    /** Fixed public holidays the business-day roll skips. */
756	    private static final Set<LocalDate> HOLIDAYS = Set.of(
757	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
758	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
759	        LocalDate.parse("2026-12-28"));
760	
761	    /**
762	     * Roll a registration date forward onto a business day: a Saturday, Sunday, or listed
763	     * public holiday is moved forward to the next non-holiday weekday; a plain weekday is
764	     * returned unchanged.
765	     */
766	    private static LocalDate toBusinessDay(LocalDate date) {
767	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
768	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
769	            || HOLIDAYS.contains(date)) {
770	            date = date.plusDays(1);
771	        }
772	        return date;
773	    }
