775	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
776	    @Override
777	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
778	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
779	        if (currentOwner == null) {
780	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
781	        }
782	        if (!normalizeEmail(ownerFieldsDto)) {
783	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
784	                "The supplied email address is invalid");
785	        }
786	        if (!normalizePostcode(ownerFieldsDto)) {
787	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
788	                "The supplied postcode is invalid for the owner's city");
789	        }
790	        if (!normalizeAddresses(ownerFieldsDto)) {
791	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
792	                "An address is required (supply either 'addressLine1' or 'address')");
793	        }
794	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
795	        if (normalizedTelephone == null) {
796	            throw new RestRejectionException(HttpStatus.BAD_REQUEST,
797	                "The supplied telephone number is invalid");
798	        }
799	        currentOwner.setAddress(ownerFieldsDto.getAddress());
800	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
801	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
802	        currentOwner.setCity(ownerFieldsDto.getCity());
803	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
804	        currentOwner.setLastName(ownerFieldsDto.getLastName());
805	        currentOwner.setTelephone(normalizedTelephone);
806	        currentOwner.setEmail(ownerFieldsDto.getEmail());
807	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
808	        this.clinicService.saveOwner(currentOwner);
809	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
810	    }
