133	    /**
134	     * The owner's region, read from the leading REGION segment of the
135	     * {@code <REGION><FY><HASH8><CHK>} memberId assigned on creation: the run of leading
136	     * letters before the first (fiscal-year) digit. Returns 'UNKNOWN' when no memberId has
137	     * been assigned (e.g. legacy owners predating the region-and-hash identity).
138	     */
139	    default String locality(Owner owner) {
140	        String id = owner.getMemberId();
141	        if (id == null) {
142	            return "UNKNOWN";
143	        }
144	        String body = identifierBody(id);
145	        int regionEnd = regionLength(body);
146	        return regionEnd == 0 ? "UNKNOWN" : body.substring(0, regionEnd);
