148	
149	    /**
150	     * The plain {@code <REGION><FY><HASH8><CHK>} body of a memberId with the leading
151	     * version-2 {@link #VERSION_TAG 'V2'} tag removed, so the user-facing locality and
152	     * fiscal year read the plain region and fiscal-year segments rather than the tag. A
153	     * memberId that does not carry the tag (e.g. a legacy value) is returned unchanged.
154	     */
155	    private static String identifierBody(String memberId) {
156	        return memberId.startsWith(VERSION_TAG) ? memberId.substring(VERSION_TAG.length()) : memberId;
157	    }
158	
159	    /**
160	     * The length of the leading REGION segment of a memberId body: the run of leading
161	     * letters before the first digit (which begins the two-digit fiscal-year segment).
162	     */
163	    private static int regionLength(String memberId) {
164	        int i = 0;
165	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
166	            i++;
167	        }
168	        return i;
169	    }
