194	    /**
195	     * The second-level labels of the known disposable email providers (the label immediately
196	     * before the top-level domain of each blocked disposable domain). Used to recognise
197	     * disposable-adjacent domains - subdomains or other-TLD near-misses that share a label with
198	     * one of these providers.
199	     */
200	    java.util.Set<String> DISPOSABLE_PROVIDER_LABELS =
201	        java.util.Set.of("mailinator", "tempmail", "guerrillamail");
202	
203	    /**
204	     * The owner's risk flag: true when the owner warrants a manual risk review because any one of
205	     * these holds - it is a possible duplicate ({@link Owner#getPossibleDuplicate()} is true), its
206	     * email domain is {@link #disposableAdjacent(String) disposable-adjacent}, or its city is over
207	     * its soft capacity ({@link Owner#getCapacityWarning()} is true, i.e. the city already held 40
208	     * or more owners when this owner was created); otherwise false.
209	     */
210	    default Boolean riskFlag(Owner owner) {
211	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
212	            || Boolean.TRUE.equals(owner.getCapacityWarning())
213	            || disposableAdjacent(owner.getEmail());
214	    }
215	
216	    /**
217	     * Whether the given email's domain is disposable-adjacent: not itself a blocked disposable
218	     * domain (those are rejected on create and never stored), but a subdomain or other-TLD
219	     * near-miss that carries one of the known {@link #DISPOSABLE_PROVIDER_LABELS disposable
220	     * provider labels} as one of its dot-separated domain labels (e.g. 'mail.mailinator.com' or
221	     * 'mailinator.net'). Returns false when the email is absent or its domain contains no such
222	     * label.
223	     */
224	    default boolean disposableAdjacent(String email) {
225	        if (email == null || email.isBlank()) {
226	            return false;
227	        }
228	        int at = email.lastIndexOf('@');
229	        if (at < 0 || at == email.length() - 1) {
230	            return false;
231	        }
232	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
233	        for (String label : domain.split("\\.")) {
234	            if (DISPOSABLE_PROVIDER_LABELS.contains(label)) {
235	                return true;
236	            }
237	        }
238	        return false;
239	    }
