241	    /**
242	     * The owner's membership points. Starts at 0; gains 2 when an email address is present,
243	     * 1 when the owner has no namesakes (namesakeCount is 0), 2 for a household of 3 or more
244	     * (householdSize is 3 or greater), and 3 when the owner's tenure spans at least one
245	     * elapsed fiscal year (the current fiscal year, starting 1 July, is later than the
246	     * registrationDate's fiscal year). Because a newly created owner registers in the current
247	     * fiscal year, the tenure points are only earned once the fiscal year has rolled over
248	     * since registration.
249	     */
250	    default Integer membershipPoints(Owner owner) {
251	        int points = 0;
252	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
253	        if (hasEmail) {
254	            points += 2;
255	        }
256	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
257	        if (noNamesakes) {
258	            points += 1;
259	        }
260	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
261	            points += 2;
262	        }
263	        if (owner.getRegistrationDate() != null
264	            && fiscalEndYear(java.time.LocalDate.now())
265	                - fiscalEndYear(owner.getRegistrationDate()) >= 1) {
266	            points += 3;
267	        }
268	        return points;
269	    }
