271	    /**
272	     * The owner's numeric membership level, derived from {@link #membershipPoints(Owner)}:
273	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points, and level 4
274	     * for 6 or more points.
275	     *
276	     * <p>The derived level is then capped by the owner's {@code membershipLevelCap} when one is
277	     * present: a new owner's level cannot exceed one above the current maximum membership level
278	     * among their existing household members, so the cap (recorded on the owner at creation as
279	     * that maximum plus one) is applied here. A {@code null} cap means the owner had no existing
280	     * household member, so no cap applies.
281	     */
282	    default Integer membershipLevel(Owner owner) {
283	        int points = membershipPoints(owner);
284	        int level;
285	        if (points <= 1) {
286	            level = 1;
287	        }
288	        else if (points <= 3) {
289	            level = 2;
290	        }
291	        else if (points <= 5) {
292	            level = 3;
293	        }
294	        else {
295	            level = 4;
296	        }
297	        Integer cap = owner.getMembershipLevelCap();
298	        if (cap != null && level > cap) {
299	            return cap;
300	        }
301	        return level;
302	    }
