304	    /**
305	     * The fiscal year, starting on 1 July, that a date falls in, expressed as the last two
306	     * digits of the calendar year in which the fiscal year ends. Dates on or after 1 July
307	     * belong to the fiscal year ending the following calendar year (e.g. 2026-08-10 -&gt; 27);
308	     * dates before 1 July belong to the fiscal year ending in the same calendar year
309	     * (e.g. 2026-03-01 -&gt; 26).
310	     */
311	    private static int fiscalEndYear(java.time.LocalDate date) {
312	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
313	    }
314	
315	    /**
316	     * The owner's fiscal year, formatted 'FY&lt;YY&gt;' where YY is the two-digit fiscal-year
317	     * (FY) segment of the memberId — the two digits immediately following the leading REGION
318	     * segment (e.g. memberId 'NSW271A2B3C4D5' -&gt; 'FY27'). Returns {@code null} when no
319	     * memberId has been assigned.
320	     */
321	    default String fiscalYear(Owner owner) {
322	        String id = owner.getMemberId();
323	        if (id == null) {
324	            return null;
325	        }
326	        String body = identifierBody(id);
327	        int regionEnd = regionLength(body);
328	        if (regionEnd + 2 > body.length()) {
329	            return null;
330	        }
331	        return "FY" + body.substring(regionEnd, regionEnd + 2);
332	    }
333	
334	    /**
335	     * Known E.164 country calling codes used to split the stored telephone into its
336	     * country code and national number for display. Longer codes are matched first so a
337	     * '+61' number is not mistaken for a '+6...' one.
338	     */
339	    java.util.List<String> COUNTRY_CODES = java.util.List.of("61", "1");
340	
341	    /**
342	     * The stored E.164 telephone formatted for humans: the country code, a space, and the
343	     * national digits grouped in threes (e.g. '+61412345678' becomes '+61 412 345 678').
344	     * Returns the stored value unchanged when it is {@code null} or not in the expected
345	     * '+'-prefixed all-digits E.164 form.
346	     */
347	    default String telephoneDisplay(Owner owner) {
348	        String telephone = owner.getTelephone();
349	        if (telephone == null || !telephone.startsWith("+")) {
350	            return telephone;
351	        }
352	        String digits = telephone.substring(1);
353	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
354	            return telephone;
355	        }
356	        String countryCode = COUNTRY_CODES.stream()
357	            .filter(digits::startsWith)
358	            .findFirst()
359	            .orElse(digits.substring(0, 1));
360	        String national = digits.substring(countryCode.length());
361	        StringBuilder sb = new StringBuilder("+").append(countryCode);
362	        for (int i = 0; i < national.length(); i++) {
363	            if (i % 3 == 0) {
364	                sb.append(' ');
365	            }
366	            sb.append(national.charAt(i));
367	        }
368	        return sb.toString();
369	    }
370	
371	    /**
372	     * The upper-cased first letters of firstName and lastName, dot-separated with a
373	     * trailing dot, e.g. 'J.S.'.
374	     */
375	    default String initials(Owner owner) {
376	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
377	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
378	    }
379	
380	    /**
381	     * A stable identifier for the owner's household, derived deterministically from the
382	     * normalized last name and the postcode. Every owner sharing the same last name
383	     * (trimmed, lower-cased, whitespace collapsed) and postcode therefore receives the
384	     * same identifier: the first twelve upper-case hex characters of the SHA-256 of
385	     * '&lt;V2&gt;|&lt;normalizedLastName&gt;|&lt;postcode&gt;', where &lt;V2&gt; is the fixed
386	     * version-2 {@link #VERSION_TAG tag} mixed in so no value produced under version 1 is
387	     * produced again. A {@code null} postcode contributes the empty string.
388	     */
389	    default String householdId(Owner owner) {
390	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
391	        String key = VERSION_TAG + "|" + normalizeHouseholdKey(owner.getLastName()) + "|" + postcode;
392	        try {
393	            byte[] digest = MessageDigest.getInstance("SHA-256")
394	                .digest(key.getBytes(StandardCharsets.UTF_8));
395	            StringBuilder sb = new StringBuilder();
396	            for (int i = 0; i < 6; i++) {
397	                sb.append(String.format("%02X", digest[i]));
398	            }
399	            return sb.toString();
400	        }
401	        catch (java.security.NoSuchAlgorithmException e) {
402	            throw new IllegalStateException(e);
403	        }
404	    }
405	
406	    /**
407	     * The owner's derived identity key: the single value onto which all duplicate
408	     * detection is consolidated. It is the full lower-case hex SHA-256 digest of
409	     * '&lt;V2&gt;|&lt;normalizedTelephone&gt;|&lt;lowerEmail&gt;|&lt;soundex(lastName)&gt;',
410	     * where &lt;V2&gt; is the fixed version-2 {@link #VERSION_TAG tag} mixed in so no value
411	     * produced under version 1 is produced again. The telephone and email are the owner's
412	     * stored (already normalized) values; a {@code null} email contributes the empty string,
413	     * and the last name is reduced to its Soundex code so surnames that sound alike share the
414	     * same segment. Two owners are duplicates only when their whole identity keys are equal.
415	     */
416	    default String identityKey(Owner owner) {
417	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
418	        String email = owner.getEmail() == null ? "" : owner.getEmail();
419	        String key = VERSION_TAG + "|" + telephone + "|" + email + "|" + Soundex.of(owner.getLastName());
420	        try {
421	            byte[] digest = MessageDigest.getInstance("SHA-256")
422	                .digest(key.getBytes(StandardCharsets.UTF_8));
423	            StringBuilder sb = new StringBuilder(digest.length * 2);
424	            for (byte b : digest) {
425	                sb.append(String.format("%02x", b));
426	            }
427	            return sb.toString();
428	        }
429	        catch (java.security.NoSuchAlgorithmException e) {
430	            throw new IllegalStateException(e);
431	        }
432	    }
433	
434	    private static String normalizeHouseholdKey(String value) {
435	        if (value == null) {
436	            return "";
437	        }
438	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
439	    }
