18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.MediaType;
30	import org.springframework.http.ProblemDetail;
31	import org.springframework.http.ResponseEntity;
32	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
33	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
34	import org.springframework.security.access.AccessDeniedException;
35	import org.springframework.validation.BindingResult;
36	import org.springframework.validation.FieldError;
37	import org.springframework.web.bind.MethodArgumentNotValidException;
38	import org.springframework.web.bind.annotation.ControllerAdvice;
39	import org.springframework.web.bind.annotation.ExceptionHandler;
40	import org.springframework.web.bind.annotation.ResponseBody;
41	
42	/**
43	 * Global Exception handler for REST controllers.
44	 * <p>
45	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
46	 *
47	 * @author Vitaliy Fedoriv
48	 * @author Alexander Dudkin
49	 */
50	@ControllerAdvice
51	public class ExceptionControllerAdvice {
52	
53	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
54	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
55	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
56	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
57	
58	    /**
59	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
60	     * class.
61	     *
62	     * @param e     Object referring to the thrown exception.
63	     * @param status HTTP response status.
64	     * @param url URL request.
65	     */
66	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
67	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
68	        problemDetail.setType(URI.create(url.toString()));
69	        problemDetail.setTitle(e.getClass().getSimpleName());
70	        problemDetail.setDetail(detail);
71	        problemDetail.setProperty("timestamp", Instant.now());
72	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
73	        return problemDetail;
74	    }
75	
76	    /**
77	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
78	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
79	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
80	     * would catch it and report an authorization failure as a 500.
81	     *
82	     * @param e The {@link AccessDeniedException} to propagate
83	     * @throws AccessDeniedException always
84	     */
85	    @ExceptionHandler(AccessDeniedException.class)
86	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
87	        throw e;
88	    }
89	
90	    /**
91	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
92	     *
93	     * @param e The {@link Exception} to be handled
94	     * @param request {@link HttpServletRequest} object referring to the current request.
95	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
96	     */
97	    @ExceptionHandler(Exception.class)
98	    @ResponseBody
99	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
100	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
101	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
102	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
103	        return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(detail);
104	    }
105	
106	    /**
107	     * Handles {@link RestRejectionException} thrown by controllers when a business rule rejects a
108	     * request (typically 400, 409 or 429), rendering a uniform RFC 7807
109	     * {@code application/problem+json} body carrying the rejection's status and detail.
110	     *
111	     * @param e The {@link RestRejectionException} to be handled
112	     * @param request {@link HttpServletRequest} object referring to the current request.
113	     * @return A {@link ResponseEntity} containing the problem detail and the rejection's status
114	     */
115	    @ExceptionHandler(RestRejectionException.class)
116	    @ResponseBody
117	    public ResponseEntity<ProblemDetail> handleRestRejectionException(RestRejectionException e, HttpServletRequest request) {
118	        HttpStatus status = e.getStatus();
119	        logger.debug("Request rejected at {} {} with {}: {}",
120	            request.getMethod(),
121	            request.getRequestURI(),
122	            status,
123	            e.getMessage());
124	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
125	        return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(detail);
126	    }
127	
128	    /**
129	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
130	     * method returns a 404 Not Found status if an entity does not exist.
131	     *
132	     * @param e The {@link DataIntegrityViolationException} to be handled
133	     * @param request {@link HttpServletRequest} object referring to the current request.
134	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
135	     */
136	    @ExceptionHandler(DataIntegrityViolationException.class)
137	    @ResponseBody
138	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
139	        logger.warn("Data integrity violation at {} {}: {}",
140	            request.getMethod(),
141	            request.getRequestURI(),
142	            e.getMessage());
143	        logger.debug("Data integrity violation stacktrace", e);
144	        HttpStatus status = HttpStatus.NOT_FOUND;
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
146	        return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(detail);
147	    }
148	
149	    /**
150	     * Handles exception thrown by Bean Validation on controller methods parameters
151	     *
152	     * @param e The {@link MethodArgumentNotValidException} to be handled
153	     * @param request {@link HttpServletRequest} object referring to the current request.
154	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
155	     */
156	    @ExceptionHandler(MethodArgumentNotValidException.class)
157	    @ResponseBody
158	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
159	        HttpStatus status = HttpStatus.BAD_REQUEST;
160	        BindingErrorsResponse errors = new BindingErrorsResponse();
161	        BindingResult bindingResult = e.getBindingResult();
162	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
163	        if (bindingResult.hasErrors()) {
164	            errors.addAllErrors(bindingResult);
165	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
166	                .map(FieldError::getField)
167	                .distinct()
168	                .toList();
169	            detail.setProperty("errors", invalidFields);
170	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
171	                .map(fieldError -> {
172	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
173	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
174	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
175	                        fieldError.getField(),
176	                        defaultMessage,
177	                        rejectedValue);
178	                    return new ValidationMessageDto(message)
179	                        .putAdditionalProperty("field", fieldError.getField())
180	                        .putAdditionalProperty("rejectedValue", rejectedValue)
181	                        .putAdditionalProperty("defaultMessage", defaultMessage);
182	                })
183	                .toList();
184	            logger.debug("Validation error at {} {}: {}",
185	                request.getMethod(),
186	                request.getRequestURI(),
187	                bindingResult.getFieldErrors());
188	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
189	            return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(detail);
190	        }
191	        return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(detail);
192	    }
193	
194	}
