21	/**
22	 * Signals that a request was rejected by a business rule with a specific 4xx status
23	 * (typically {@code 400}, {@code 409} or {@code 429}). Thrown from REST controllers in
24	 * place of returning a bare status so that {@link ExceptionControllerAdvice} can render a
25	 * uniform RFC 7807 {@code application/problem+json} body for every rejection.
26	 *
27	 * <p>The exception message is used as the problem's {@code detail} member.
28	 */
29	public class RestRejectionException extends RuntimeException {
30	
31	    private final HttpStatus status;
32	
33	    public RestRejectionException(HttpStatus status, String detail) {
34	        super(detail);
35	        this.status = status;
36	    }
37	
38	    public HttpStatus getStatus() {
39	        return this.status;
40	    }
41	}
